/* aesthetic doc v0.25.0 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-ink-muted: #737373;
  --ae-line: #e9e9e9;
  --ae-ink-muted-dark: #8f8f8f;
  --ae-line-dark: #262626;
  --ae-w-medium: 550;
  --ae-w-black: 800;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) {
    --ae-ink-muted: var(--ae-ink-muted-dark);
    --ae-line: var(--ae-line-dark);
  }
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

:root.dark,
:root[data-ae-mode='dark'] {
  color-scheme: dark;
  --ae-ink-muted: var(--ae-ink-muted-dark);
  --ae-line: var(--ae-line-dark);
}

.ae-doc h1,
.ae-doc h2 {
font-weight: var(--ae-w-black);
  margin: 2.2em 0 0.6em;
}

.ae-doc h3,
.ae-doc h4 {
font-weight: var(--ae-w-medium);
  margin: 1.8em 0 0.4em;
}

.ae-doc h5,
.ae-doc h6 {
font-weight: var(--ae-w-medium);
  color: var(--ae-ink-muted);
  margin: 1.8em 0 0.4em;
}

.ae-doc h1:first-child,
.ae-doc h2:first-child,
.ae-doc h3:first-child {
margin-top: 0;
}

.ae-doc p,
.ae-doc ul,
.ae-doc ol {
margin-bottom: 0.9em;
}

.ae-doc ul,
.ae-doc ol {
padding-left: 1.4em;
}

.ae-doc li {
margin-bottom: 0.2em;
}

.ae-doc hr {
border: 0;
  border-top: 1px solid var(--ae-line);
  margin: 2.4em 0;
}

.ae-doc blockquote {
border-left: 1px solid var(--ae-line);
  padding-left: 1.4em;
  color: var(--ae-ink-muted);
  margin: 1.2em 0;
}

.ae-doc pre {
background: var(--ae-wash);
  font-size: 13px;
  line-height: 1.75;
  padding: 1.2em 1.4em;
  margin: 1.2em 0;
  overflow-x: auto;
}

.ae-doc :not(pre) > code {
background: var(--ae-wash);
  padding: 0.1em 0.35em;
}

.ae-doc img {
max-width: 100%;
}

.ae-doc {
counter-reset: ae-fig;
}

.ae-doc figure {
counter-increment: ae-fig;
  margin: 1.8em 0;
}

.ae-doc figcaption {
margin-bottom: 0.7em;
  font-family: var(--ae-font-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  color: var(--ae-ink-muted);
}

.ae-doc figcaption::before {
content: 'FIG ' counter(ae-fig) ' · ';
  color: var(--ae-ink);
  font-weight: var(--ae-w-medium);
}
